<?php
require_once __DIR__ . '/../includes/bootstrap.php'; $id = (int)($_GET['id'] ?? 0);
$statement = database()->prepare("SELECT j.*, c.name category_name, e.company_name, e.description company_description FROM jobs j JOIN job_categories c ON c.id=j.category_id JOIN employers e ON e.user_id=j.employer_id WHERE j.id=? AND j.status='active'"); $statement->execute([$id]); $job = $statement->fetch(); if (!$job) { http_response_code(404); exit('Job not found.'); }
$skills = database()->prepare('SELECT skill_name FROM job_required_skills WHERE job_id=?'); $skills->execute([$id]);
$questionCount = database()->prepare('SELECT COUNT(*) FROM quiz_questions WHERE job_id=?'); $questionCount->execute([$id]); $hasQuiz = (int) $questionCount->fetchColumn() > 0;
page_header($job['title']); ?>
<article class="card"><span class="badge"><?= e($job['category_name']) ?></span><h1><?= e($job['title']) ?></h1><p class="lead"><?= e($job['company_name']) ?> · <?= e($job['location']) ?></p><p><?= nl2br(e($job['description'])) ?></p><h2>Responsibilities</h2><p><?= nl2br(e($job['responsibilities'])) ?></p><h2>Requirements</h2><p><?= nl2br(e($job['requirements_text'])) ?></p><h2>Skills</h2><?php foreach ($skills->fetchAll() as $skill): ?><span class="badge"><?= e($skill['skill_name']) ?></span> <?php endforeach; ?><p class="meta">Preliminary quiz pass score: <?= e($job['minimum_passing_score']) ?>%</p><?php $user=current_user(); if ($user && $user['role']==='seeker' && $hasQuiz): ?><a class="button" href="../seeker/quiz.php?job_id=<?= $id ?>">Take preliminary quiz</a><?php elseif ($user && $user['role']==='seeker'): ?><p class="notice">The employer has not published quiz questions for this job yet.</p><?php elseif (!$user): ?><a class="button" href="login.php">Login to apply</a><?php endif; ?></article>
<?php page_footer(); ?>